for i, text in enumerate(human_texts, 1):
    file_path = os.path.join(HUMAN_DIR, f"human_{i:03d}.txt")
    with open(file_path, "w", encoding="utf-8") as f:
        f.write(text.strip())
        print(f"Human {i}: {len(text.split())} words")

for i, text in enumerate(ai_texts, 1):
    file_path = os.path.join(AI_DIR, f"ai_{i:03d}.txt")
    with open(file_path, "w", encoding="utf-8") as f:
        f.write(text.strip())
        print(f"AI {i}: {len(text.split())} words")

print(f"Created {len(human_texts)} human files.")
print(f"Created {len(ai_texts)} AI files.")
